def relabel_cancellations(apps, schema_editor):
    """
    The reversals already written are cancellations, not returns to the supplier.

    They are identifiable without guessing: `StockService.move` stamped the note "GRN cancelled: …" and the
    reference is the receipt itself. Leaving them as "Purchase return" would keep showing the owner a return
    that never happened — which is how this was found.
    """
    StockMovement = apps.get_model("inventory", "StockMovement")
    StockMovement.objects.filter(movement_type="purchase_return", reference_type="GoodsReceipt",
                                 note__startswith="GRN cancelled:").update(movement_type="grn_cancelled")


